$n = trim(fgets(STDIN));
$n = (int)$n;
$MOD = 1000003;
if ($n == 0) {
    echo 1 % $MOD;
    exit;
}
$e = $n - 1;
$res = 1;
$b = 3 % $MOD;
while ($e > 0) {
    if ($e & 1) {
        $res = ($res * $b) % $MOD;
    }
    $b = ($b * $b) % $MOD;
    $e >>= 1;
}
